    71→
    72→export const initialState: GuideBuilderState = {
    73→  title: "",
    74→  description: "",
    75→  difficulty: null,
    76→  timeEstimate: null,
    77→  isVibeCoded: false,
    78→  guideType: "full_app",
    79→  prerequisites: [],
    80→  whatYoullBuild: "",
    81→  techs: [],
    82→  categoryId: null,
    83→  mediaFiles: [],
    84→  blocks: [],
