    18→              cookieStore.set(name, value, options)
    19→            );
    20→          } catch {
    21→            // The `setAll` method was called from a Server Component.
    22→            // This can be ignored if you have middleware refreshing sessions.
    23→          }
    24→        },
    25→      },
    26→    }
    27→  );
    28→}
