     3→
     4→export async function fetchGuideById(guideId: string): Promise<GuideDetail | null> {
     5→  const supabase = createClient();
     6→
     7→  const { data, error } = await supabase
     8→    .from("posts")
     9→    .select(`
    10→      *,
    11→      profile:profiles!posts_user_id_fkey(*),
    12→      category:categories!posts_category_id_fkey(*),
    13→      media:post_media(*),
    14→      chat_messages(*, annotation:message_annotations(*), star:message_stars(*)),
    15→      timeline_chapters(*)
    16→    `)
    17→    .eq("id", guideId)
    18→    .eq("is_hidden", false)
    19→    .single();
    20→
    21→  if (error || !data) return null;
    22→
    23→  // Sort media and chat_messages by order
    24→  if (data.media) {
    25→    (data.media as any[]).sort((a: any, b: any) => a.order - b.order);
    26→  }
    27→  if (data.chat_messages) {
    28→    (data.chat_messages as any[]).sort((a: any, b: any) => a.order - b.order);
    29→    // Map joined annotation (array→single) and star (presence→boolean)
    30→    for (const msg of data.chat_messages as any[]) {
    31→      const annArr = msg.annotation;
    32→      msg.annotation = Array.isArray(annArr) && annArr.length > 0 ? annArr[0] : undefined;
    33→      const starArr = msg.star;
    34→      msg.is_starred = Array.isArray(starArr) ? starArr.length > 0 : !!starArr;
    35→      delete msg.star;
    36→    }
    37→  }
    38→  if (data.timeline_chapters) {
    39→    (data.timeline_chapters as any[]).sort((a: any, b: any) => a.start_order - b.start_order);
    40→  }
    41→
    42→  return data as unknown as GuideDetail;
    43→}
    44→
    45→export async function fetchGuideTitle(guideId: string): Promise<string | null> {
    46→  const supabase = createClient();
    47→
    48→  const { data, error } = await supabase
    49→    .from("posts")
    50→    .select("title")
    51→    .eq("id", guideId)
    52→    .single();
    53→
    54→  if (error || !data) return null;
    55→  return data.title;
    56→}
    57→
    58→export async function fetchGuideComments(guideId: string): Promise<Comment[]> {
    59→  const supabase = createClient();
    60→
    61→  const { data, error } = await supabase
    62→    .from("comments")
    63→    .select(`
    64→      *,
    65→      profile:profiles!comments_user_id_fkey(*)
    66→    `)
    67→    .eq("post_id", guideId)
    68→    .eq("is_hidden", false)
    69→    .order("created_at", { ascending: true });
    70→
    71→  if (error) return [];
    72→  return data as unknown as Comment[];
    73→}
    74→
    75→export function buildCommentTree(flat: Comment[]): Comment[] {
    76→  const map = new Map<string, Comment>();
    77→  const roots: Comment[] = [];
    78→
    79→  for (const c of flat) {
    80→    map.set(c.id, { ...c, replies: [] });
    81→  }
    82→
    83→  for (const c of flat) {
    84→    const node = map.get(c.id)!;
    85→    if (c.parent_id && map.has(c.parent_id)) {
    86→      map.get(c.parent_id)!.replies!.push(node);
    87→    } else {
    88→      roots.push(node);
    89→    }
