     4→export async function fetchProfileByUsername(username: string): Promise<Profile | null> {
     5→  const supabase = createClient();
     6→
     7→  const { data, error } = await supabase
     8→    .from("profiles")
     9→    .select("*")
    10→    .eq("username", username)
    11→    .single();
    12→
    13→  if (error) return null;
