    17→export async function fetchUserGuides(userId: string): Promise<Guide[]> {
    18→  const supabase = createClient();
    19→
    20→  const { data, error } = await supabase
    21→    .from("posts")
    22→    .select(`
    23→      *,
    24→      profile:profiles!posts_user_id_fkey(*),
    25→      media:post_media(*)
    26→    `)
    27→    .eq("user_id", userId)
    28→    .eq("is_hidden", false)
    29→    .order("created_at", { ascending: false });
    30→
    31→  if (error) return [];
