    57→    .from("post_likes")
    58→    .select(`
    59→      post:posts!post_likes_post_id_fkey(
    60→        *,
    61→        profile:profiles!posts_user_id_fkey(*),
    62→        media:post_media(*)
    63→      )
    64→    `)
    65→    .eq("user_id", userId)
    66→    .order("created_at", { ascending: false });
    67→
    68→  if (error) return [];
    69→  return (data ?? []).map((row: any) => row.post).filter(Boolean) as Guide[];
    70→}
    71→
    72→export async function fetchUserSavedGuides(userId: string): Promise<Guide[]> {
    73→  const supabase = createClient();
    74→
    75→  const { data, error } = await supabase
    76→    .from("post_saves")
    77→    .select(`
    78→      post:posts!post_saves_post_id_fkey(
    79→        *,
    80→        profile:profiles!posts_user_id_fkey(*),
    81→        media:post_media(*)
    82→      )
    83→    `)
    84→    .eq("user_id", userId)
    85→    .order("created_at", { ascending: false });
    86→
    87→  if (error) return [];
    88→  return (data ?? []).map((row: any) => row.post).filter(Boolean) as Guide[];
    89→}
    90→
    91→export async function updateProfile(
    92→  userId: string,
    93→  updates: Partial<Pick<Profile, "display_name" | "bio" | "show_likes" | "show_saves" | "github_url" | "linkedin_url">>
    94→): Promise<Profile | null> {
    95→  const supabase = createClient();
    96→
    97→  // Strip undefined values — Supabase rejects them
    98→  const clean: Record<string, unknown> = {};
    99→  for (const [key, value] of Object.entries(updates)) {
   100→    if (value !== undefined) clean[key] = value;
   101→  }
   102→
   103→  const { data, error } = await supabase
   104→    .from("profiles")
   105→    .update(clean)
   106→    .eq("id", userId)
   107→    .select("*")
   108→    .single();
   109→
   110→  if (error) {
   111→    console.error("Failed to update profile:", error.message);
   112→    return null;
   113→  }
   114→  return data as Profile;
   115→}
