    25→
    26→export function GuideActions({
    27→  guideId,
    28→  userId,
    29→  initialLiked,
    30→  initialSaved,
    31→  likesCount,
    32→  savesCount,
    33→  isOwner,
    34→  guide,
    35→  onGuideUpdated,
    36→  onGuideDeleted,
    37→}: GuideActionsProps) {
