    12→
    13→interface GuideActionsProps {
    14→  guideId: string;
    15→  userId?: string | null;
    16→  initialLiked: boolean;
    17→  initialSaved: boolean;
    18→  likesCount: number;
    19→  savesCount: number;
    20→  isOwner?: boolean;
    21→  guide?: GuideDetail | null;
    22→  onGuideUpdated?: (updated: GuideDetail) => void;
    23→  onGuideDeleted?: () => void;
    24→}
    25→
    26→export function GuideActions({
    27→  guideId,
    28→  userId,
    29→  initialLiked,
    30→  initialSaved,
    31→  likesCount,
    32→  savesCount,
    33→  isOwner,
    34→  guide,
    35→  onGuideUpdated,
    36→  onGuideDeleted,
    37→}: GuideActionsProps) {
    38→  const router = useRouter();
    39→  const [liked, setLiked] = useState(initialLiked);
    40→  const [saved, setSaved] = useState(initialSaved);
    41→  const [likes, setLikes] = useState(likesCount);
    42→  const [saves, setSaves] = useState(savesCount);
    43→
    44→  // Sync with parent when async status check resolves
    45→  useEffect(() => setLiked(initialLiked), [initialLiked]);
    46→  useEffect(() => setSaved(initialSaved), [initialSaved]);
    47→  const [copied, setCopied] = useState(false);
    48→
    49→  // Owner menu state
    50→  const [menuOpen, setMenuOpen] = useState(false);
    51→  const [editOpen, setEditOpen] = useState(false);
    52→  const [confirmDelete, setConfirmDelete] = useState(false);
    53→  const [deleting, setDeleting] = useState(false);
    54→  const menuRef = useRef<HTMLDivElement>(null);
    55→
    56→  // Close menu on outside click
    57→  useEffect(() => {
    58→    if (!menuOpen) return;
    59→    function handleClick(e: MouseEvent) {
    60→      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
    61→        setMenuOpen(false);
    62→      }
    63→    }
    64→    document.addEventListener("mousedown", handleClick);
    65→    return () => document.removeEventListener("mousedown", handleClick);
    66→  }, [menuOpen]);
    67→
    68→  async function handleLike() {
    69→    if (!userId) {
    70→      router.push("/login");
    71→      return;
    72→    }
    73→    const wasLiked = liked;
    74→    setLiked(!wasLiked);
    75→    setLikes((c) => (wasLiked ? c - 1 : c + 1));
    76→    await toggleLike(guideId, userId, wasLiked);
    77→  }
    78→
    79→  async function handleSave() {
    80→    if (!userId) {
    81→      router.push("/login");
    82→      return;
    83→    }
    84→    const wasSaved = saved;
    85→    setSaved(!wasSaved);
    86→    setSaves((c) => (wasSaved ? c - 1 : c + 1));
    87→    await toggleSave(guideId, userId, wasSaved);
    88→  }
    89→
    90→  function handleShare() {
    91→    navigator.clipboard.writeText(window.location.href);
    92→    setCopied(true);
    93→    setTimeout(() => setCopied(false), 2000);
    94→  }
    95→
    96→  async function handleDelete() {
    97→    setDeleting(true);
    98→    const ok = await deleteGuide(guideId);
    99→    if (ok) {
   100→      onGuideDeleted?.();
   101→      router.push("/");
   102→    }
   103→    setDeleting(false);
   104→    setConfirmDelete(false);
   105→  }
   106→
   107→  return (
   108→    <>
   109→      <div className="flex flex-wrap gap-2">
   110→        <button
   111→          onClick={handleLike}
   112→          className={cn(
   113→            "flex items-center gap-1.5 rounded-full px-3 py-1.5 text-sm font-medium transition-colors",
   114→            liked
   115→              ? "bg-red-500/10 text-red-500"
   116→              : "bg-muted text-muted-foreground hover:text-foreground"
   117→          )}
   118→        >
   119→          <Heart size={16} className={liked ? "fill-current" : ""} />
   120→          {formatNumber(likes)}
   121→        </button>
   122→
   123→        <button
   124→          onClick={handleSave}
   125→          className={cn(
   126→            "flex items-center gap-1.5 rounded-full px-3 py-1.5 text-sm font-medium transition-colors",
   127→            saved
   128→              ? "bg-accent/10 text-accent"
   129→              : "bg-muted text-muted-foreground hover:text-foreground"
   130→          )}
   131→        >
   132→          <Bookmark size={16} className={saved ? "fill-current" : ""} />
   133→          {formatNumber(saves)}
   134→        </button>
   135→
   136→        <button
   137→          onClick={handleShare}
   138→          className="flex items-center gap-1.5 rounded-full bg-muted px-3 py-1.5 text-sm font-medium text-muted-foreground hover:text-foreground transition-colors"
   139→        >
   140→          <Link2 size={16} />
   141→          {copied ? "Copied!" : "Share"}
   142→        </button>
   143→
   144→        {/* Owner actions */}
   145→        {isOwner && guide && (
   146→          <div className="relative" ref={menuRef}>
   147→            <button
   148→              onClick={() => setMenuOpen(!menuOpen)}
   149→              className="flex items-center justify-center rounded-full bg-muted p-2 text-muted-foreground hover:text-foreground transition-colors"
   150→            >
   151→              <MoreHorizontal size={16} />
   152→            </button>
   153→            {menuOpen && (
   154→              <div className="absolute right-0 top-full z-10 mt-1 w-36 rounded-xl bg-surface py-1 shadow-lg ring-1 ring-white/10">
   155→                <button
   156→                  onClick={() => {
   157→                    setMenuOpen(false);
   158→                    setEditOpen(true);
   159→                  }}
   160→                  className="flex w-full items-center gap-2 px-3 py-2 text-sm text-foreground hover:bg-muted transition-colors"
   161→                >
   162→                  <Pencil size={14} />
   163→                  Edit
   164→                </button>
   165→                <button
   166→                  onClick={() => {
   167→                    setMenuOpen(false);
   168→                    setConfirmDelete(true);
   169→                  }}
   170→                  className="flex w-full items-center gap-2 px-3 py-2 text-sm text-red-500 hover:bg-muted transition-colors"
   171→                >
   172→                  <Trash2 size={14} />
   173→                  Delete
   174→                </button>
   175→              </div>
   176→            )}
   177→          </div>
   178→        )}
   179→      </div>
   180→
   181→      {/* Edit modal */}
   182→      {isOwner && guide && (
   183→        <EditGuideModal
   184→          open={editOpen}
   185→          guide={guide}
   186→          onClose={() => setEditOpen(false)}
   187→          onSaved={(updated) => onGuideUpdated?.(updated)}
   188→        />
   189→      )}
   190→
   191→      {/* Delete confirmation */}
   192→      <ConfirmDialog
   193→        open={confirmDelete}
   194→        onClose={() => setConfirmDelete(false)}
   195→        onConfirm={handleDelete}
   196→        title="Delete guide"
   197→        message="Are you sure you want to delete this guide? This action cannot be undone."
   198→        loading={deleting}
   199→      />
   200→    </>
   201→  );
   202→}
