    41→  const [likes, setLikes] = useState(likesCount);
    42→  const [saves, setSaves] = useState(savesCount);
    43→
    44→  // Sync with parent when async status check resolves
    45→  useEffect(() => setLiked(initialLiked), [initialLiked]);
    46→  useEffect(() => setSaved(initialSaved), [initialSaved]);
    47→  const [copied, setCopied] = useState(false);
    48→
    49→  // Owner menu state
