     3→import { useState, useCallback } from "react";
     4→import { MessageCircle } from "lucide-react";
     5→import { Avatar } from "@/components/ui/avatar";
     6→import { CommentItem } from "./comment-item";
     7→import { createComment, buildCommentTree } from "@/lib/supabase/queries/guide-detail";
     8→import { formatNumber } from "@/lib/utils";
     9→import type { Comment } from "@/types";
    10→
    11→interface CommentSectionProps {
    12→  postId: string;
    13→  initialComments: Comment[];
    14→  userId?: string | null;
    15→  userUsername?: string;
    16→  userAvatarUrl?: string | null;
    17→}
    18→
    19→export function CommentSection({
    20→  postId,
    21→  initialComments,
    22→  userId,
    23→  userUsername,
    24→  userAvatarUrl,
    25→}: CommentSectionProps) {
    26→  const [flatComments, setFlatComments] = useState(initialComments);
    27→  const [content, setContent] = useState("");
    28→  const [submitting, setSubmitting] = useState(false);
    29→
    30→  const tree = buildCommentTree(flatComments);
    31→
    32→  async function handleSubmit() {
    33→    if (!userId || !content.trim()) return;
    34→    setSubmitting(true);
    35→
    36→    const newComment = await createComment(postId, userId, content.trim());
    37→
    38→    if (newComment) {
    39→      setFlatComments((prev) => [...prev, newComment]);
    40→      setContent("");
    41→    }
    42→    setSubmitting(false);
    43→  }
    44→
    45→  const handleReplyAdded = useCallback((reply: Comment) => {
    46→    setFlatComments((prev) => [...prev, reply]);
    47→  }, []);
    48→
    49→  const handleCommentUpdated = useCallback((commentId: string, content: string) => {
    50→    setFlatComments((prev) =>
    51→      prev.map((c) => (c.id === commentId ? { ...c, content } : c))
    52→    );
    53→  }, []);
    54→
    55→  const handleCommentDeleted = useCallback((commentId: string) => {
    56→    setFlatComments((prev) => prev.filter((c) => c.id !== commentId));
    57→  }, []);
    58→
    59→  return (
    60→    <div>
    61→      {/* Header */}
    62→      <div className="mb-4 flex items-center gap-2">
    63→        <MessageCircle size={18} className="text-muted-foreground" />
    64→        <h2 className="text-lg font-semibold text-foreground">Comments</h2>
    65→        {flatComments.length > 0 && (
    66→          <span className="rounded-full bg-muted px-2 py-0.5 text-xs font-medium text-muted-foreground">
    67→            {formatNumber(flatComments.length)}
    68→          </span>
    69→        )}
    70→      </div>
    71→
    72→      {/* Compose box */}
    73→      {userId && (
    74→        <div className="mb-6 flex gap-3">
    75→          <Avatar
    76→            userId={userId}
    77→            username={userUsername ?? "?"}
    78→            avatarUrl={userAvatarUrl}
    79→            size="md"
    80→          />
    81→          <div className="flex-1">
    82→            <textarea
    83→              value={content}
    84→              onChange={(e) => setContent(e.target.value)}
    85→              placeholder="Add a comment..."
    86→              rows={3}
    87→              className="w-full resize-none rounded-lg bg-muted px-4 py-3 text-sm text-foreground placeholder:text-muted-foreground outline-none focus:ring-2 focus:ring-accent/30 transition-shadow"
    88→            />
    89→            <div className="mt-2 flex justify-end">
    90→              <button
    91→                onClick={handleSubmit}
    92→                disabled={!content.trim() || submitting}
    93→                className="rounded-full bg-accent px-4 py-1.5 text-sm font-medium text-accent-foreground disabled:opacity-50 hover:opacity-90 transition-opacity"
    94→              >
    95→                Comment
    96→              </button>
    97→            </div>
    98→          </div>
    99→        </div>
   100→      )}
   101→
   102→      {/* Comments list */}
   103→      {tree.length === 0 ? (
   104→        <div className="flex flex-col items-center justify-center py-12 text-center">
   105→          <div className="mb-3 flex h-14 w-14 items-center justify-center rounded-2xl bg-muted">
   106→            <MessageCircle size={24} className="text-muted-foreground" />
   107→          </div>
   108→          <p className="text-sm text-muted-foreground">No comments yet</p>
   109→        </div>
   110→      ) : (
   111→        <div className="flex flex-col gap-4">
   112→          {tree.map((comment) => (
   113→            <CommentItem
   114→              key={comment.id}
   115→              comment={comment}
   116→              postId={postId}
   117→              userId={userId}
   118→              userUsername={userUsername}
   119→              userAvatarUrl={userAvatarUrl}
   120→              onReplyAdded={handleReplyAdded}
   121→              onCommentUpdated={handleCommentUpdated}
   122→              onCommentDeleted={handleCommentDeleted}
   123→            />
   124→          ))}
   125→        </div>
   126→      )}
   127→    </div>
   128→  );
   129→}
   130→

