// NO "use client"
import { notFound } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { ProfilePageClient } from "@/components/profile/profile-page-client";
import {
  fetchProfileByUsernameServer,
  fetchUserGuidesServer,
