      .from("profiles")
      .select("*")
      .eq("id", user.id)
      .single();
    profile = data;
  }

  return (
    <GuideDetailClient
      guide={guide}
      initialComments={comments}
      recommended={recommended}
      user={user}
      profile={profile}
    />
  );
